  "style": [
    "nocturnal synth pop",
    "warm analog color",
    "modern restraint"
  ],
  "mood": [
    "lonely",
    "luminous",
    "patient"
  ],
  "must_include": [
    "6 to 8 differentiated roles",
    "room for vocal in verse",
    "chorus widens register",
    "second verse is not a duplicate"
  ],
  "must_avoid": [
    "lead melody competing with imagined vocal throughout",
    "all tracks entering together",
    "constant cymbal wash"
  ],
  "instrument_roles": [
    "drums",
    "bass",
    "main chords",
    "counter motif",
    "pad",
    "transition texture",
    "optional instrumental hook"
  ],
  "delivery": [
    "44 bars",
    "6 to 8 tracks",
    "CC dynamics on sustained roles"
  ],
  "score_focus": [
    "orchestration",
    "density arc",
    "vocal space",
    "song development"
  ],
  "mode_a": true
}

